#define RGB32_SIZE (_Max_Height / 16 * 5 << 13)
#define PATH3TAG_SIZE (((_Max_Height / 16 * 240 + 10) * 4 + 63) / 64 << 9)
#define DEMUX_BUFF_SIZE 0x30000
#define AUDIO_BUFF_SIZE 0xc000

